-- 024: borrador inicial de la Guía del líder, sacado de documentos de la iglesia (REDIL, normas de espacios y equipos, Riel, Ruta de crecimiento).
-- Todo queda "por confirmar" salvo lo que describe el propio sistema: los líderes y el asistente solo ven lo confirmado.
-- Solo se siembra si la guía está vacía, así nunca pisa lo que ya se haya escrito.

INSERT INTO leader_guide (status, category, question, answer, contact, source, sort)
SELECT * FROM (VALUES
  ('confirmada', 'Mi enlace y el sistema', '¿Cómo envío el reporte semanal de mi grupo?', 'Abre tu enlace personal (el que te envió la iglesia) y entra a la pestaña Reporte. Escribe la fecha de la reunión, cuántos asistieron (miembros, invitados y el total), la ofrenda y lo que pasó en la reunión, y pulsa Enviar. Si te equivocaste, vuelve a enviar la misma fecha y se corrige.', '', 'Sistema de la iglesia', 0),
  ('confirmada', 'Mi enlace y el sistema', '¿Cómo actualizo los datos de mi grupo o mis datos personales?', 'En tu enlace personal, pestaña Datos del grupo: el día, la hora y el lugar de la reunión, tus datos y tu foto. Al guardar, la información llega a la iglesia.', '', 'Sistema de la iglesia', 1),
  ('confirmada', 'Mi enlace y el sistema', 'Perdí mi enlace o dejó de funcionar, ¿qué hago?', 'Escríbele a la iglesia para que te generen un enlace nuevo. Cuando se genera uno nuevo, el anterior deja de servir. No compartas tu enlace con otras personas: con él se pueden enviar reportes de tu grupo.', 'Administración de la iglesia', 'Sistema de la iglesia', 2),
  ('confirmada', 'Mi enlace y el sistema', '¿Qué más puedo hacer desde mi enlace?', 'Planificar el mes (pestaña Planificador), marcar el avance de tu gente en la Ruta de crecimiento, hacer el análisis F.O.D.A. del trimestre y ver el Reporte trimestral con las ofrendas, los visitantes y la asistencia de tu grupo.', '', 'Sistema de la iglesia', 3),
  ('por_confirmar', 'Espacios y equipos', '¿Qué no se permite dentro de las instalaciones?', 'No se permite fumar, tomar bebidas alcohólicas ni consumir drogas dentro y fuera del auditorio. Tampoco ingerir alimentos, bebidas ni chucherías dentro de las instalaciones, rayar, pegar chicles ni pararse en las sillas, ni traer sillas del mismo modelo y color de las de la iglesia.', '', 'Normativa de uso de instalaciones (2017)', 4),
  ('por_confirmar', 'Espacios y equipos', '¿Para qué se puede usar el auditorio?', 'Se usa exclusivamente para talleres de crecimiento personal, educativo y/o espiritual. No se permiten actividades bailables, folclóricas o culturales. Se pueden hacer graduaciones educativas siempre que el espacio alcance para la cantidad de personas.', '', 'Normativa de uso de instalaciones (2017)', 5),
  ('por_confirmar', 'Espacios y equipos', '¿Cómo pido materiales o equipos para mi actividad?', 'Una vez que esté autorizado, solicítalos por escrito y con tiempo. Al recibirlos, revisa el equipo y avisa de inmediato si ves algún daño o deterioro.', 'Pastor asistente', 'Normas de uso de materiales y equipos (2017)', 6),
  ('por_confirmar', 'Espacios y equipos', '¿Puedo sacar un equipo de la iglesia o moverlo de lugar?', 'No. Está prohibido usar materiales y equipos fuera de las instalaciones o moverlos de su lugar sin autorización previa del pastor asistente.', 'Pastor asistente', 'Normas de uso de materiales y equipos (2017)', 7),
  ('por_confirmar', 'Espacios y equipos', '¿Quién maneja el equipo de sonido?', 'Lo manejan el personal de medios de la iglesia o las personas que autorice el pastor asistente.', 'Pastor asistente', 'Normas de uso de materiales y equipos (2017)', 8),
  ('por_confirmar', 'Espacios y equipos', 'Cuando termina mi actividad, ¿qué hago con los materiales y equipos?', 'Todos deben devolverse a su lugar de almacenamiento o funcionamiento al terminar la actividad.', '', 'Normas de uso de materiales y equipos (2017)', 9),
  ('por_confirmar', 'Grupos de cuidado', '¿Puedo sacar o meter a alguien de mi grupo o de un ministerio?', 'No sin consultar antes. Se comunica a Jesueth, no para pedir permiso sino para decidirlo juntos.', 'Jesueth', 'Minuta REDIL 06/08/2022', 10),
  ('por_confirmar', 'Grupos de cuidado', '¿Cuál debe ser el plan de un líder?', 'Multiplicarse: ese debe ser siempre su plan. No llevar el ministerio de forma improvisada: planear con actividades y comunicar al pastor los días de celebración.', '', 'Minuta REDIL 06/08/2022', 11),
  ('por_confirmar', 'Grupos de cuidado', '¿Qué tan importante es la puntualidad?', 'De suma importancia. Fue uno de los acuerdos del REDIL.', '', 'Minuta REDIL 06/08/2022', 12),
  ('por_confirmar', 'Grupos de cuidado', '¿Qué pasa con las vacaciones de los grupos de cuidado?', 'En 2022 se acordó que las vacaciones ministeriales se activaban el 1 de septiembre con un congreso de Grupos de Cuidado; los grupos se mantenían, menos el de adolescentes, que se reunía cada 15 días, y los líderes podían hacer una actividad de cierre. Confirma qué aplica este año.', '', 'Minuta REDIL 06/08/2022', 13),
  ('por_confirmar', 'Grupos de cuidado', 'Una persona recién creyó en mi grupo, ¿qué hago con ella?', 'El nuevo creyente debe conectarse a un grupo de cuidado, no al Riel. El protocolo completo para nuevos creyentes estaba pendiente de definir.', '', 'Minuta REDIL 06/08/2022', 14),
  ('por_confirmar', 'Ofrendas y cuidado pastoral', '¿Quién lleva la Santa Cena a una casa?', 'Deben ir los pastores, no los líderes, y solo cuando sea realmente una necesidad de la persona.', '', 'Minuta REDIL 06/08/2022', 15),
  ('por_confirmar', 'Ofrendas y cuidado pastoral', '¿Cómo funciona la cesta de amor?', 'Tiene prioridad quien lo necesita según la Palabra: viudas, huérfanos y extranjeros. Los líderes deben estar atentos a las necesidades de su grupo; si no hay de esos casos, se le da a quien tenga necesidad. Se procura no dar dinero. Hay tres opciones: que lo haga el líder solo, que lo haga con el grupo, o que se apoye con la cesta de amor de la iglesia. Si el grupo no puede llevarla todos juntos, puede ir el líder en representación.', 'Mirna', 'Minuta REDIL 06/08/2022', 16),
  ('por_confirmar', 'Ofrendas y cuidado pastoral', '¿Se pueden recoger diezmos y ofrendas en el grupo?', 'Se acordó incentivar a los grupos a diezmar y se contempló entregar en los grupos sobres para recoger diezmos y ofrendas.', '', 'Minuta REDIL 06/08/2022', 17),
  ('por_confirmar', 'Formación (Riel)', '¿Cómo inscribo a alguien en el Riel?', 'Con cuidado y con filtro: se regresaron personas que no aplicaban y eso puede hacer daño. Verifica que la persona cumpla antes de inscribirla. En 2022 las inscripciones se hacían en agosto para empezar en septiembre.', '', 'Minuta REDIL 06/08/2022', 18),
  ('por_confirmar', 'Formación (Riel)', '¿Qué cursos del Riel hay y cuándo se dan?', 'En la segunda temporada de 2022: Discipulado (domingos 9:00 am, de septiembre a diciembre), Taller de Padre (domingos 11:00 am, de octubre a noviembre) y Sirviendo con Excelencia (domingos 7:00 am, de octubre a noviembre), en el Salón de Riel. Confirma los horarios y salones actuales.', '', 'Propuesta Inicio Riel 2da Temporada (2022)', 19),
  ('por_confirmar', 'Formación (Riel)', '¿Cuánto dura la pasantía de servidores?', 'Se aprobó una pasantía de servidores al finalizar el taller. Dura 8 semanas, pero es flexible.', '', 'Minuta REDIL 06/08/2022', 20),
  ('por_confirmar', 'Formación (Riel)', '¿Cómo es el comisionamiento?', 'Se entregan los certificados un sábado en la iglesia y el domingo se presenta a las personas ante la congregación, en lotes, en los tres servicios. La lista de quienes se presentan se envía antes a los coordinadores. Al comisionar, se les explica cuál es el siguiente paso. Los coordinadores informan quiénes están sirviendo pero todavía no han sido comisionados.', 'Coordinadores', 'Minuta REDIL 06/08/2022', 21),
  ('por_confirmar', 'Ruta de crecimiento', '¿Cuál es la ruta de crecimiento de la iglesia?', 'Amigos, Invitados, Discípulos, Padres espirituales, Líderes de cuidado, Líderes asesores, Pastores de congregación y Ministros.', '', 'Tabla Ruta de crecimiento', 22),
  ('por_confirmar', 'Ruta de crecimiento', '¿Qué se busca en cada etapa de la persona?', 'Atendidos: que desarrollen interés y piensen "deseo volver". Cuidados: que desarrollen vínculos y piensen "deseo quedarme". Formados: que desarrollen compromiso y piensen "aquí deseo servir". Comisionados: que desarrollen su llamado y piensen "este es mi propósito, a esto Dios me llamó".', '', 'Tabla Ruta de crecimiento', 23),
  ('por_confirmar', 'Ruta de crecimiento', '¿Con qué cursos se forma una persona?', 'Vida (evangelismo relacional), Nueva Vida, Bautismo, Discipulado (Primeros pasos y De fe), Sirviendo con Excelencia, Taller de Padre, Taller de Líder, Taller de Liderazgo asesor, Escuela de pastores y Formación ministerial. También hay enseñanzas como Viviendo en libertad, prosperidad bíblica, DARTE y noviazgo y matrimonio.', '', 'Tabla Ruta de crecimiento', 24)
) AS v(status, category, question, answer, contact, source, sort)
WHERE NOT EXISTS (SELECT 1 FROM leader_guide);
